download.windows_online_command:
$repo = 'gaofeng21cn/one-person-lab-app'
$name = 'install-docker-webui.ps1'
$cache = Join-Path $env:LOCALAPPDATA 'OnePersonLab\installer-cache'
$p = Join-Path $cache $name
$id = Join-Path $cache 'install-docker-webui.identity.json'
try {
  $release = Invoke-RestMethod "https://api.github.com/repos/$repo/releases/latest"
  if ($release.draft -or $release.prerelease -or $release.tag_name -notmatch '^v[0-9A-Za-z._-]+$') { throw 'Latest did not resolve to an eligible exact Release.' }
  $asset = @($release.assets | Where-Object name -eq $name)
  if ($asset.Count -ne 1 -or $asset[0].digest -notmatch '^sha256:[0-9a-f]{64}$' -or [int64]$asset[0].size -le 0) { throw 'Release asset identity is missing or ambiguous.' }
  $expectedUrl = "https://github.com/$repo/releases/download/$($release.tag_name)/$name"
  if ($asset[0].browser_download_url -ne $expectedUrl) { throw 'Release asset URL mismatch.' }
  New-Item -ItemType Directory -Force $cache | Out-Null
  $candidate = "$p.new"
  Invoke-WebRequest -UseBasicParsing $expectedUrl -OutFile $candidate
  $sha = (Get-FileHash $candidate -Algorithm SHA256).Hash.ToLowerInvariant()
  if ((Get-Item $candidate).Length -ne [int64]$asset[0].size -or $sha -ne $asset[0].digest.Substring(7)) { Remove-Item $candidate -Force; throw 'Downloaded installer size or SHA-256 mismatch.' }
  Move-Item $candidate $p -Force
  @{schema='opl_verified_installer_cache.v1';repository=$repo;release_tag=$release.tag_name;asset=@{name=$name;url=$expectedUrl;sha256=$sha;size_bytes=[int64]$asset[0].size}} | ConvertTo-Json -Depth 4 | Set-Content $id -Encoding UTF8
} catch {
  if (-not (Test-Path $p) -or -not (Test-Path $id)) { throw }
  $saved = Get-Content $id -Raw | ConvertFrom-Json
  $sha = (Get-FileHash $p -Algorithm SHA256).Hash.ToLowerInvariant()
  if ($saved.schema -ne 'opl_verified_installer_cache.v1' -or $saved.repository -ne $repo -or $saved.release_tag -notmatch '^v[0-9A-Za-z._-]+$' -or $saved.asset.name -ne $name -or $saved.asset.url -ne "https://github.com/$repo/releases/download/$($saved.release_tag)/$name" -or $saved.asset.sha256 -ne $sha -or [int64]$saved.asset.size_bytes -ne (Get-Item $p).Length) { throw 'No valid verified installer cache is available.' }
  Write-Warning "Using verified installer cache from $($saved.release_tag): $($_.Exception.Message)"
}
powershell -ExecutionPolicy Bypass -File $p -EnableAutoUpdate -Yes
